import{_ as i,l as s,o as e,c as l,v as t,p as n,x as r,d,i as c,S as E}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"结构体内存布局","description":"","frontmatter":{"title":"结构体内存布局","date":"2026-09-10T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/struct-layout.md","filePath":"cs/struct-layout.md","lastUpdated":1789023840000}'),p={name:"cs/struct-layout.md"};function B(h,a,A,m,u,_){const o=s("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="结构体内存布局" tabindex="-1">结构体内存布局 <a class="header-anchor" href="#结构体内存布局" aria-label="Permalink to &quot;结构体内存布局&quot;">​</a></h1><div class="epigraph"><p>结构体把若干对象按声明次序排进一块存储；偏移是编译器算好的常数，不是运行时查表。</p><footer>—— 据 Kernighan &amp; Ritchie, The C Programming Language, 2nd ed.；ISO/IEC 9899；Bryant and O&#39;Hallaron, Computer Systems: A Programmer&#39;s Perspective 整理</footer></div><p>上一课<a href="/cs/array-decay">数组与指针衰减</a>把连续元素钉死：数组是同类型的一排，衰减会丢掉长度。本课不重讲衰减，也不从「对象系统」另起。缺口是：要在一块存储里放下<strong>不同类型</strong>的字段，并且用名字而不是下标去取。编译器如何给每个字段一个固定偏移，字段之间为什么会出现空洞。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><code>struct</code> 是对象的聚合。成员按声明顺序分配，地址递增。取成员 <code>s.x</code> 在机器上是「基址加偏移再按该成员类型解释」。缺口因此不是语法点号，而是<strong>布局成为 ABI 的一部分</strong>：同一结构体在调用双方必须有相同偏移，否则传值、传指针都会各读各的。数组做不到异构；结构体专门补这一块。</p><p>把结构体当成「一袋命名变量」而忽略它们挤在同一对象里，会漏掉：取址 <code>&amp;s.x</code> 得到的指针别名的是结构体的一部分；通过结构体指针改一个字段，与通过字段指针写入是同一存储。上一课的别名规则在此继续有效。</p><h3 id="结构体不是「字段的集合类型」而已" tabindex="-1">结构体不是「字段的集合类型」而已 <a class="header-anchor" href="#结构体不是「字段的集合类型」而已" aria-label="Permalink to &quot;结构体不是「字段的集合类型」而已&quot;">​</a></h3><p>语言保证顺序，不保证紧凑。字段之间、结构体尾部都可以有填充，使得下一字段或下一数组元素满足对齐。本课先承认「有偏移、可能有洞」；洞为什么必须存在、怎样改声明顺序缩小洞，是<a href="/cs/alignment-padding">下一课</a>。也不要把结构体等价于 C++ 对象：这里还没有虚表、没有构造，只有布局。</p><p><span class="marginnote">K&amp;R 用结构体描述二进制记录与系统调用参数。CSAPP 强调：结构体的机器视图就是基址加常数偏移。ISO C 允许实现插入填充，但不允许重排字段顺序——顺序是程序员写进源码的契约。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>声明顺序即内存顺序。第一个成员偏移为 0。指向结构体的指针可以转换成指向首成员的指针，来回可逆。结构体赋值与传值拷贝整块对象（含填充比特，那些比特的值未指定）。数组作为成员时不衰减：它跟着结构体一起被拷贝。</p>',11)),(e(),n(E,null,{default:r(()=>[c(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E7%BB%93%E6%9E%84%E4%BD%93%E5%AF%B9%E8%B1%A1%22%5D%20--%3E%20F0%5B%22%E5%AD%97%E6%AE%B5%E4%B8%80%EF%BC%9A%E5%81%8F%E7%A7%BB%200%22%5D%0A%20%20S%20--%3E%20F1%5B%22%E5%AD%97%E6%AE%B5%E4%BA%8C%EF%BC%9A%E5%81%8F%E7%A7%BB%E4%B8%BA%E5%B8%B8%E6%95%B0%22%5D%0A%20%20S%20--%3E%20PAD%5B%22%E5%8F%AF%E8%83%BD%E7%9A%84%E5%A1%AB%E5%85%85%22%5D%0A%20%20S%20--%3E%20PTR%5B%22%E5%8F%96%E5%9D%80%E5%BE%97%E5%88%B0%E6%88%90%E5%91%98%E6%8C%87%E9%92%88%22%5D%0A%20%20PTR%20--%3E%20ALIAS%5B%22%E4%B8%8E%E7%BB%93%E6%9E%84%E4%BD%93%E5%85%B1%E4%BA%AB%E5%AD%98%E5%82%A8%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p><code>offsetof</code> 把偏移变成可打印的整数，便于核对 ABI。联合体让若干成员共享起始地址，本课只点名：同一存储的另一种解释，别名规则更紧。位域把若干比特挤进存储单元，可移植布局更弱，主干不依赖它。</p><p>柔性数组成员把「最后一项是变长数组」写进类型，对象大小不再是编译期常数，分配必须按实际元素数来。这仍是同一套偏移规则，只是尾部长度由运行时决定。与指针指向别处的堆块相比，柔性成员把变长数据贴在同一对象里，寿命自动一起结束，有利于 RAII。本课主干仍用定长字段；知道有这条扩展，就不必用 <code>char tail[1]</code> 的老写法去骗过编译器。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>固定偏移让字段访问编译成一条带位移的访存，没有运行时名字查找。这是 C 作为系统语言能直接描述设备寄存器与报文头的原因。代价是：布局一旦被二进制协议或动态库钉死，改字段顺序或插入字段就会破坏兼容。后课模块与头文件会把「共享布局」写成跨翻译单元的契约。</p><p>结构体参数按值传递时，调用约定要决定整块怎么进栈或寄存器——那是<a href="/cs/calling-convention-preview">调用约定直觉</a>的缺口。本课只准备好「一块带内部偏移的对象」。嵌套结构体把内层布局嵌进外层偏移；数组的结构体则是该布局的周期重复。</p><p>布局一旦被系统调用、文件格式或另一门语言的 FFI 钉死，就不再只是「这个 .c 里的方便」。调用约定会按整块大小与对齐把结构体放进栈或寄存器；改一个 <code>int</code> 为 <code>int64</code> 而不重编所有包含者，就是静默的 ABI 破裂。后课头文件把这份布局复制到每个翻译单元，正是为了让偏移一致。位域与打包属性会打破可移植偏移，主干算法不要依赖它们来省那几个填充字节。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不计算每种 ABI 的具体填充表，不讲虚函数指针。下一课专门解释对齐约束如何强迫这些洞。后课默认：结构体按声明顺序布局；成员访问是基址加偏移；字段指针与结构体别名同一对象。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>结构体是异构字段的连续对象，偏移在编译期确定。</li><li>字段顺序是契约；填充可以存在，但实现不得擅自重排。</li><li>成员取址得到的指针与结构体别名；按值拷贝带走整块。</li><li>下一课解释对齐为何插入填充。</li><li>出处：K&amp;R 结构体；ISO C 聚合布局；CSAPP 对偏移寻址的说明。</li></ul>',10))])}const S=i(p,[["render",B]]);export{P as __pageData,S as default};
